/**
 * Test the verification of a JSON-able value in isolation.
 */

// This code has been automatically generated by aas-core-codegen.
// Do NOT edit or append.

import * as AasTypes from "../src/types";
import * as AasVerification from "../src/verification";

/**
 * Collect the path and the message of every error of `errors`.
 */
function pathsAndMessages(
  errors: IterableIterator<AasVerification.VerificationError>
): Array<[string, string]> {
  const result = new Array<[string, string]>();
  for (const error of errors) {
    result.push([error.path.toString(), error.message]);
  }
  return result;
}

test("a deeply nested value is JSON-able", () => {
  const value: AasTypes.JsonValue = {
    a: [1, 1.5, "x", true, [2], { b: "text" }],
    c: { d: { e: [] } }
  };

  expect(pathsAndMessages(AasVerification.verifyJsonValue(value))).toStrictEqual(
    []
  );
});

test("the walk of a JSON-able value is depth first", () => {
  // NOTE (mristin):
  // A breadth-first walk would report the shallow `["z"]` before the deeper
  // `["a"]["deep"]`, although the latter comes first in the value.
  const value: AasTypes.JsonValue = {
    a: { deep: Number.NaN },
    z: Number.POSITIVE_INFINITY
  };

  const paths = pathsAndMessages(AasVerification.verifyJsonValue(value)).map(
    ([path]) => path
  );

  expect(paths).toStrictEqual(['["a"]["deep"]', '["z"]']);
});

test("an index and a key render as a subscript", () => {
  const value: AasTypes.JsonValue = { "a b": [0, { "c'd": Number.NaN }] };

  const pathsAndCauses = pathsAndMessages(
    AasVerification.verifyJsonValue(value)
  );

  expect(pathsAndCauses.length).toStrictEqual(1);
  expect(pathsAndCauses[0][0]).toStrictEqual('["a b"][1]["c\'d"]');
});

test("the segments of a JSON-able path carry their container", () => {
  const inner = { deep: Number.NaN };
  const value: AasTypes.JsonValue = { a: inner };

  const errors = Array.from(AasVerification.verifyJsonValue(value));
  expect(errors.length).toStrictEqual(1);

  const segments = errors[0].path.segments;
  expect(segments.length).toStrictEqual(2);

  const outer = segments[0];
  expect(outer).toBeInstanceOf(AasVerification.KeySegment);
  expect((outer as AasVerification.KeySegment).object).toBe(value);
  expect((outer as AasVerification.KeySegment).key).toStrictEqual("a");

  const nested = segments[1];
  expect(nested).toBeInstanceOf(AasVerification.KeySegment);
  expect((nested as AasVerification.KeySegment).object).toBe(inner);
  expect((nested as AasVerification.KeySegment).key).toStrictEqual("deep");
});

test("neither an infinity nor a not-a-number is JSON-able", () => {
  for (const number of [
    Number.POSITIVE_INFINITY,
    Number.NEGATIVE_INFINITY,
    Number.NaN
  ]) {
    const pathsAndCauses = pathsAndMessages(
      AasVerification.verifyJsonValue([number])
    );

    expect(pathsAndCauses.length).toStrictEqual(1);
    expect(pathsAndCauses[0][0]).toStrictEqual("[0]");
    expect(pathsAndCauses[0][1]).toContain(
      "neither finite nor representable in JSON"
    );
  }
});

test("a value of an unexpected type is refused", () => {
  // NOTE (mristin):
  // `JsonValue` rules a function out, but a JavaScript caller can hand one
  // over all the same, which is the very reason this verification exists.
  const value = { a: () => 1 } as unknown as AasTypes.JsonValue;

  const pathsAndCauses = pathsAndMessages(
    AasVerification.verifyJsonValue(value)
  );

  expect(pathsAndCauses.length).toStrictEqual(1);
  expect(pathsAndCauses[0][0]).toStrictEqual('["a"]');
  expect(pathsAndCauses[0][1]).toContain("but got: function");
});

test("a null is refused at any depth", () => {
  const value = { a: [null] } as unknown as AasTypes.JsonValue;

  const pathsAndCauses = pathsAndMessages(
    AasVerification.verifyJsonValue(value)
  );

  expect(pathsAndCauses.length).toStrictEqual(1);
  expect(pathsAndCauses[0][0]).toStrictEqual('["a"][0]');
  expect(pathsAndCauses[0][1]).toContain("but got: null");
});

test("a JSON-able array has to be an array", () => {
  const value = { a: 1 } as unknown as AasTypes.JsonArray;

  const pathsAndCauses = pathsAndMessages(
    AasVerification.verifyJsonArray(value)
  );

  expect(pathsAndCauses.length).toStrictEqual(1);
  expect(pathsAndCauses[0][0]).toStrictEqual("");
  expect(pathsAndCauses[0][1]).toContain("Expected a JSON-able array");
});

test("a JSON-able object has to be an object", () => {
  const value = [1, 2] as unknown as AasTypes.JsonObject;

  const pathsAndCauses = pathsAndMessages(
    AasVerification.verifyJsonObject(value)
  );

  expect(pathsAndCauses.length).toStrictEqual(1);
  expect(pathsAndCauses[0][0]).toStrictEqual("");
  expect(pathsAndCauses[0][1]).toContain("Expected a JSON-able object");
});

test("the content is verified beneath the shape", () => {
  const value: AasTypes.JsonObject = { a: [{ b: Number.NaN }] };

  const pathsAndCauses = pathsAndMessages(
    AasVerification.verifyJsonObject(value)
  );

  expect(pathsAndCauses.length).toStrictEqual(1);
  expect(pathsAndCauses[0][0]).toStrictEqual('["a"][0]["b"]');
});

